import React, { useMemo, useState } from 'react';

const outcomeLabels = { registered: 'Registered', appointment: 'Appointment', undecided: 'Undecided', promised: 'Promised', declined: 'Declined' };

export default function SalesReportsPanel({ reports = [] }) {
  const [filters, setFilters] = useState({ from: '', to: '', outcome: '', employee: '' });
  const filtered = useMemo(() => reports.filter((report) => (!filters.from || report.date_visited >= filters.from) && (!filters.to || report.date_visited <= filters.to) && (!filters.outcome || report.outcome === filters.outcome) && (!filters.employee || (report.employee_name || '').toLowerCase().includes(filters.employee.toLowerCase()))), [filters, reports]);
  const update = (name, value) => setFilters((current) => ({ ...current, [name]: value }));
  return <section className="leave-section sales-reports-section" id="sales-reports"><div className="leave-section-heading"><div><p className="leave-kicker">SALES OPERATIONS</p><h2>Daily sales reports</h2><p className="leave-muted">Review client visits, registrations, appointments, and follow-ups.</p></div><span className="section-meta">{filtered.length} reports</span></div><div className="sales-report-filters"><label>From<input type="date" value={filters.from} onChange={(event) => update('from', event.target.value)} /></label><label>To<input type="date" value={filters.to} onChange={(event) => update('to', event.target.value)} /></label><label>Employee<input placeholder="Search employee" value={filters.employee} onChange={(event) => update('employee', event.target.value)} /></label><label>Outcome<select value={filters.outcome} onChange={(event) => update('outcome', event.target.value)}><option value="">All outcomes</option>{Object.entries(outcomeLabels).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></label></div><div className="leave-table-wrap compact-table"><table className="leave-table"><thead><tr><th>Employee</th><th>Client</th><th>Type</th><th>Location</th><th>Date</th><th>Outcome</th><th>Documents</th></tr></thead><tbody>{filtered.length === 0 ? <tr><td colSpan="7">No sales reports match the selected filters.</td></tr> : filtered.map((report) => <tr key={report.id}><td>{report.employee_name || 'Employee'}</td><td>{report.business_owner_name || report.agent_name}</td><td>{report.customer_type === 'sub_agent' ? 'Sub-agent' : 'Agent / dealer'}</td><td>{report.business_location || '-'}</td><td>{report.date_visited}</td><td><span className="sales-outcome">{outcomeLabels[report.outcome] || report.outcome}</span></td><td>{Object.values(report.documents || {}).filter(Boolean).length + (report.uploaded_files || []).length}</td></tr>)}</tbody></table></div></section>;
}
